INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solitaire-japan', 'GAMEBOY', 'Solitaire (Japan)', '1991', 'Board', 'GameTek', '1', 'Card / Board', 'Card game.', 'Clear the board in various Solitaire modes.', 'Portable Solitaire (JP).', 'A clean and simple implementation of the classic card game, featuring several variations like Klondike and Spider.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solitaire-funpak-usa-europe', 'GAMEBOY', 'Solitaire Funpak (USA, Europe)', '1991', 'Board', 'GameTek', '1-2', 'Card / Board', 'Card game collection.', 'Master 12 different solitaire games.', 'Solitaire Funpak (USA/EU).', 'A comprehensive collection of card games, offering hours of logic-based gameplay and customizable card backs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solomons-club-europe', 'GAMEBOY', 'Solomon''s Club (Europe)', '1991', 'Puzzle', 'Tecmo', '1', 'Action Puzzle', 'Action puzzle.', 'Use fire and ice blocks to reach the exit.', 'Solomon''s Key spin-off.', 'A prequel to the NES classic Solomon''s Key; players solve 100+ puzzles by creating and destroying blocks to find keys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solomons-club-japan', 'GAMEBOY', 'Solomon''s Club (Japan)', '1991', 'Puzzle', 'Tecmo', '1', 'Action Puzzle', 'Action puzzle.', 'Use fire and ice blocks to reach the exit.', 'Solomon''s Club (Japan).', 'The Japanese release, featuring the same brain-bending puzzle mechanics and secret room locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solomons-club-usa', 'GAMEBOY', 'Solomon''s Club (USA)', '1991', 'Puzzle', 'Tecmo', '1', 'Action Puzzle', 'Action puzzle.', 'Use fire and ice blocks to reach the exit.', 'Solomon''s Club (USA).', 'The North American version, known for its high difficulty curve and rewarding logic-based challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-3d-blast-5-unl', 'GAMEBOY', 'Sonic 3D Blast 5 (Unl)', '2003', 'Platformer', 'Unlicensed', '1', 'Fan-made Platformer', 'Side-scrolling platformer (Unl).', 'Defeat the bosses and stop Robotnik.', 'Sonic 3D Blast bootleg.', 'An unlicensed 2D platformer that attempts to recreate the Sonic experience using assets from other 8-bit games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-6-unl', 'GAMEBOY', 'Sonic 6 (Unl)', '2004', 'Platformer', 'Unlicensed', '1', 'Fan-made Platformer', 'Side-scrolling platformer (Unl).', 'Speed through the levels to the end.', 'Sonic 6 (Unlicensed).', 'A famous "pirate" game that is actually a hack of Somari (itself a hack), featuring Sonic in Mario-style levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soreike!-amida-kun-japan', 'GAMEBOY', 'Soreike! Amida-kun (Japan)', '1992', 'Puzzle', 'Jaleco', '1', 'Party Puzzle', 'Puzzle / Strategy.', 'Guide the characters through the Amida lines.', 'Amida-kuji logic game.', 'Based on the traditional Japanese lottery game; players must manipulate paths to ensure characters reach the correct goals.');
