INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soreyuke!!-kid-japan', 'GAMEBOY', 'Soreyuke!! Kid (Japan)', '1992', 'Action', 'Jaleco', '1', 'Action Platformer', 'Side-scrolling platformer.', 'Stop the underground empire.', 'Boomer''s Adventure (Japan).', 'Known as Boomer''s Adventure in ASMIK World in the West; a top-down action game where you dig holes to trap enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soukoban-japan', 'GAMEBOY', 'Soukoban (Japan)', '1990', 'Puzzle', 'Thinking Rabbit', '1', 'Logic Puzzle', 'Grid-based puzzle.', 'Push all crates onto the target squares.', 'The original Sokoban.', 'The definitive portable version of the classic logic puzzle. Players must carefully move boxes without getting them stuck in corners.');
