INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-europe', 'GAMEBOY', 'Space Invaders (Europe)', '1990', 'Shooter', 'Taito', '1', 'Fixed Shooter', 'Fixed-screen shooter.', 'Destroy the descending alien waves.', 'Space Invaders (Europe).', 'A faithful port of the Taito classic, featuring a special Super Game Boy mode that mimics the original arcade cabinet''s colors.');
